export function projectLonLat(lon: number, lat: number) {
  const innerW = MAP.width - MAP.pad * 2;
  const innerH = MAP.height - MAP.pad * 2;
  return {
    x: MAP.pad + ((lon - MAP.lon0) / (MAP.lon1 - MAP.lon0)) * innerW,
    y: MAP.pad + ((MAP.lat1 - lat) / (MAP.lat1 - MAP.lat0)) * innerH,
  };
}
